def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (ignore it)
        if '+' in version:
            version = version.split('+')[0]

        # Split pre-release
        if '-' in version:
            main_part, pre_release = version.split('-', 1)
        else:
            main_part = version
            pre_release = None

        # Parse MAJOR.MINOR.PATCH
        parts = main_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        pre_release_identifiers = []
        if pre_release:
            for identifier in pre_release.split('.'):
                # Check if all digits
                if identifier.isdigit():
                    pre_release_identifiers.append((0, int(identifier)))
                else:
                    pre_release_identifiers.append((1, identifier))

        return (major, minor, patch, pre_release_identifiers)

    def compare_key(item):
        index, version = item
        major, minor, patch, pre_release_identifiers = parse_version(version)

        # Version with pre-release sorts before version without
        # So we use the length: empty list (no pre-release) sorts after non-empty
        # We need: no pre-release comes AFTER pre-release for same major.minor.patch
        # So if no pre-release, use a tuple that sorts after any pre-release tuple
        if not pre_release_identifiers:
            pre_release_key = (1,)  # Sorts after (0, ...)
        else:
            pre_release_key = (0, pre_release_identifiers)

        return (major, minor, patch, pre_release_key, index)

    # Create list of (original_index, version) to maintain input order for equal precedence
    indexed_versions = [(i, v) for i, v in enumerate(versions)]

    # Sort using the comparison key
    sorted_versions = sorted(indexed_versions, key=compare_key)

    # Extract just the version strings
    return [v for _, v in sorted_versions]

